<?php
$root=dirname(__DIR__);$migration=file_get_contents($root.'/src/Core/Infrastructure/Migration/Migrator.php');$service=file_get_contents($root.'/src/Core/Application/Finance/OperationalCashLedgerService.php');$repository=file_get_contents($root.'/src/Core/Infrastructure/Repository/OperationalCashRepository.php');$controller=file_get_contents($root.'/src/Admin/Controller/OperationalCashbookController.php');$plugin=file_get_contents($root.'/delnavazan-platform.php');
$assert=static function(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);};
foreach(array('finance_cash_accounts','finance_cash_transactions','finance_cash_transfers','finance_cash_commands','finance_cash_reconciliations')as$table)$assert(substr_count($migration,'CREATE TABLE {$p}'.$table.' ')===1,'Cashbook schema must declare exactly one additive '.$table.' table');
$assert(str_contains($migration,"'038_operational_cashbook_authority'")&&str_contains($plugin,"DZN_PLATFORM_SCHEMA_VERSION', '38'"),'Cashbook migration and schema version must advance together');
$assert(str_contains($migration,'UNIQUE KEY command_key_digest(command_key_digest)')&&str_contains($migration,'UNIQUE KEY reverses_transaction(reverses_transaction_id)')&&str_contains($migration,'UNIQUE KEY reverses_transfer(reverses_transfer_id)')&&str_contains($migration,'UNIQUE KEY account_opening(account_id,opening_slot)'),'Commands, opening balances and corrections must be uniquely auditable');
$assert(str_contains($migration,'UNIQUE KEY transfer_leg(transfer_id,transfer_leg)')&&str_contains($migration,'unpaired cashbook conversion or reversal'),'Paired transfers must have one verified leg per account');
$assert(str_contains($migration,"array('australia','Australia account','AUD',2)")&&str_contains($migration,"array('iran','Iran account','TOM',0)"),'Only the two requested currency accounts may be seeded');
$assert(str_contains($service,'FinanceIdempotency::payload')&&str_contains($repository,'FinanceSupport::begin()')&&str_contains($repository,'FinanceSupport::commit()')&&str_contains($service,"'result_type'=>\$result['result_type']"),'Cashbook commands must use the shared Finance idempotency and transaction foundations');
$assert(str_contains($service,'convert_to_iran')&&str_contains($service,"'rate_tom_per_aud'=>\$rate")&&str_contains($service,"'source_amount_minor'=>\$source")&&str_contains($service,"'destination_amount_minor'=>\$destination"),'Conversions must persist both amounts and the operator-supplied historical rate');
$assert(str_contains($service,'reverse_transfer')&&str_contains($service,'reverse_transaction'),'Corrections must append reversals');
$assert(str_contains($service,'balance_adjustment')&&str_contains($migration,"'balance_adjustment'"),'An opening balance can be corrected with an auditable append-only adjustment');
$assert(str_contains($service,'finance_cash_reconciliations')&&str_contains($service,'$system-$actual'),'Reconciliation must compare recorded ledger and statement balances without mutation');
$assert(str_contains($migration,'statement_balance_minor bigint NOT NULL')&&!str_contains($migration,'statement_balance_minor bigint unsigned NOT NULL'),'Statement reconciliation must support signed external balances');
$assert(str_contains($service,'OperationalCashRule::statementBalance'),'Reconciliation must use the signed statement-balance parser');
$assert(str_contains($repository,'effective_kind')&&str_contains($repository,'original.transaction_kind')&&str_contains($repository,"IN ('income','expense')"),'Reports must account for reversals while excluding transfers');
$assert(!preg_match('/\$wpdb->(?:update|delete)\s*\(/',$repository.$service),'Cashbook entries must not be rewritten or deleted');
$assert(str_contains($controller,"'record','convert','reconcile','reverse','reverse_transfer'")&&str_contains($controller,'check_admin_referer')&&str_contains($controller,'wp_safe_redirect'),'Admin write actions must be nonce-checked and redirect after posting');
$assert(str_contains($controller,'current_user_can(OperationalCashLedgerService::MANAGE_CAPABILITY)')&&str_contains($plugin,'OperationalCashbookController::register()'),'The cashbook must use the Finance admin capability and be bootstrapped');
$assert(!str_contains($service,'wp_remote_')&&!str_contains($service,'PaymentExecutionController'),'The operational cashbook must not call provider or payment execution paths');
echo "operational-cashbook-contract: pass\n";
